// Rebuilds css/frutiger-aero-wallpaper-embed.css from assets/frutiger-aero-wallpaper.jpg.
// VS Code's window can't load file:/// images, so the wallpaper is inlined as a data URI.
// Run with: npm run build:embed

const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
const jpg = path.join(root, 'assets', 'frutiger-aero-wallpaper.jpg');
const out = path.join(root, 'css', 'frutiger-aero-wallpaper-embed.css');

const b64 = fs.readFileSync(jpg).toString('base64');
const css =
  '/* Auto-generated by scripts/build-wallpaper-embed.js. Do not edit by hand.\n' +
  '   Embeds assets/frutiger-aero-wallpaper.jpg as a data URI, because VS Code\n' +
  '   (vscode-file:// origin) blocks file:/// images. Load AFTER frutiger-aero-full-wallpaper.css. */\n' +
  `:root { --aero-wallpaper-url: url("data:image/jpeg;base64,${b64}") !important; }\n`;

fs.writeFileSync(out, css);
console.log(`Wrote ${path.relative(root, out)} (${(css.length / 1024).toFixed(0)} KB)`);
